package com.dirtlegends.client;

import com.dirtlegends.DirtLegends;
import com.dirtlegends.entity.MotoVehicleEntity;
import net.minecraft.client.model.*;
import net.minecraft.client.render.entity.model.EntityModelLayer;
import net.minecraft.client.render.entity.model.SinglePartEntityModel;
import net.minecraft.util.Identifier;
import net.minecraft.util.math.MathHelper;

/** Blocky motocross bike. Generated by tools/gen.py (shapes and texture layout must match). */
public class DirtBikeModel extends SinglePartEntityModel<MotoVehicleEntity> {
    public static final EntityModelLayer LAYER = new EntityModelLayer(Identifier.of(DirtLegends.MOD_ID, "dirt_bike"), "main");
    private final ModelPart top;
    private final ModelPart root;
    private final ModelPart frame;
    private final ModelPart fork;
    private final ModelPart frontWheel;
    private final ModelPart rearWheel;

    public DirtBikeModel(ModelPart top) {
        this.top = top;
        this.root = top.getChild("root");
        this.frame = root.getChild("frame");
        this.fork = root.getChild("fork");
        this.frontWheel = fork.getChild("front_wheel");
        this.rearWheel = root.getChild("rear_wheel");
    }

    @SuppressWarnings("unused")
    public static TexturedModelData getTexturedModelData() {
        ModelData data = new ModelData();
        ModelPartData base = data.getRoot();
        ModelPartData root = base.addChild("root", ModelPartBuilder.create(), ModelTransform.pivot(0.0f, 24.0f, 0.0f));
        ModelPartData frame = root.addChild("frame", ModelPartBuilder.create().uv(0, 0).cuboid(-2.0f, -10.0f, -3.0f, 4.0f, 4.0f, 6.0f).uv(20, 0).cuboid(-3.0f, -8.0f, -2.0f, 6.0f, 2.0f, 4.0f).uv(40, 0).cuboid(-3.0f, -14.0f, -7.0f, 6.0f, 3.0f, 6.0f).uv(64, 0).cuboid(-4.0f, -13.0f, -8.0f, 1.0f, 3.0f, 4.0f).uv(74, 0).cuboid(3.0f, -13.0f, -8.0f, 1.0f, 3.0f, 4.0f).uv(84, 0).cuboid(-2.0f, -16.0f, -2.0f, 4.0f, 2.0f, 10.0f).uv(0, 12).cuboid(-3.0f, -14.0f, 2.0f, 6.0f, 3.0f, 5.0f).uv(22, 12).cuboid(-2.0f, -14.0f, 8.0f, 4.0f, 1.0f, 7.0f).uv(44, 12).cuboid(-1.0f, -11.0f, -6.0f, 2.0f, 5.0f, 2.0f).uv(52, 12).cuboid(-2.0f, -6.0f, 0.0f, 4.0f, 1.0f, 11.0f).uv(82, 12).cuboid(3.0f, -11.0f, 0.0f, 2.0f, 2.0f, 12.0f),
                ModelTransform.pivot(0.0f, 0.0f, 0.0f));
        ModelPartData fork = root.addChild("fork", ModelPartBuilder.create().uv(110, 12).cuboid(-3.0f, 0.0f, -1.0f, 1.0f, 11.0f, 2.0f).uv(116, 12).cuboid(2.0f, 0.0f, -1.0f, 1.0f, 11.0f, 2.0f).uv(0, 26).cuboid(-3.0f, -1.0f, -1.0f, 6.0f, 1.0f, 3.0f).uv(18, 26).cuboid(-7.0f, -2.0f, 0.0f, 14.0f, 1.0f, 1.0f).uv(48, 26).cuboid(-2.0f, 0.0f, -3.0f, 4.0f, 4.0f, 1.0f).uv(58, 26).cuboid(-2.0f, 5.0f, -6.0f, 4.0f, 1.0f, 9.0f),
                ModelTransform.pivot(0.0f, -16.0f, -10.0f));
        ModelPartData front_wheel = fork.addChild("front_wheel", ModelPartBuilder.create().uv(84, 26).cuboid(-1.0f, -5.0f, -3.0f, 2.0f, 10.0f, 6.0f).uv(100, 26).cuboid(-1.0f, -3.0f, -5.0f, 2.0f, 6.0f, 10.0f).uv(0, 42).cuboid(-1.0f, -3.0f, -3.0f, 2.0f, 6.0f, 6.0f, new Dilation(0.2f)),
                ModelTransform.pivot(0.0f, 11.0f, 0.0f));
        ModelPartData rear_wheel = root.addChild("rear_wheel", ModelPartBuilder.create().uv(84, 26).cuboid(-1.0f, -5.0f, -3.0f, 2.0f, 10.0f, 6.0f).uv(100, 26).cuboid(-1.0f, -3.0f, -5.0f, 2.0f, 6.0f, 10.0f).uv(0, 42).cuboid(-1.0f, -3.0f, -3.0f, 2.0f, 6.0f, 6.0f, new Dilation(0.2f)),
                ModelTransform.pivot(0.0f, -5.0f, 10.0f));
        return TexturedModelData.of(data, 128, 64);
    }

    @Override
    public ModelPart getPart() {
        return top;
    }

    @Override
    public void setAngles(MotoVehicleEntity entity, float limbAngle, float limbDistance, float animationProgress, float headYaw, float headPitch) {
        float tickDelta = MathHelper.clamp(animationProgress - entity.age, 0.0f, 1.0f);
        float comp = entity.getSuspension(tickDelta) * 2.5f;
        root.pitch = entity.getBodyPitch(tickDelta) * MathHelper.RADIANS_PER_DEGREE;
        root.roll = -entity.getLean(tickDelta) * MathHelper.RADIANS_PER_DEGREE;
        fork.yaw = entity.getSteerAngle(tickDelta) * MathHelper.RADIANS_PER_DEGREE;
        frame.pivotY = comp;
        fork.pivotY = -16.0f + comp;
        frontWheel.pivotY = 11.0f - comp;
        float spin = entity.getWheelSpin(tickDelta);
        frontWheel.pitch = spin;
        rearWheel.pitch = spin;
    }
}
